window.docContents[222].resolve({"/4___-Representations-of-finite-groups___-Basic-results/4___11___-Historical-interlude___-Georg-Frobenius___s-___Principle-of-Horse-Trade___/#chapter-04___section-4-11":{"contents":"\n\n","context":"Introduction to Representation Theory\t4. Representations of finite groups: Basic results","header":"4.11. Historical interlude: Georg Frobenius's \"Principle of Horse Trade\"","id":"/4___-Representations-of-finite-groups___-Basic-results/4___11___-Historical-interlude___-Georg-Frobenius___s-___Principle-of-Horse-Trade___/#chapter-04___section-4-11"},"/5___-Representations-of-finite-groups___-Further-results/5___2___-Algebraic-numbers-and-algebraic-integers/Algebraic-conjugates-of-sums-are-sums-of-algebraic-conjugates/#Chapter5___Lemma5___2___6":{"contents":"Lemma 5.2.6. If \\alpha_1, \\ldots, \\alpha_m are algebraic numbers, then all algebraic conjugates to \\alpha_1 + \\cdots + \\alpha_m are of the form \\alpha_1' + \\cdots + \\alpha_m', where \\alpha_i' are some algebraic conjugates of \\alpha_i.\nProof. It suffices to prove this for two summands. If \\alpha_i are eigenvalues of rational matrices A_i of smallest size (i.e., their characteristic polynomials are the minimal polynomials of \\alpha_i), then \\alpha_1 + \\alpha_2 is an eigenvalue of A := A_1 \\otimes \\mathrm{Id} + \\mathrm{Id} \\otimes A_2. Therefore, so is any algebraic conjugate to \\alpha_1 + \\alpha_2. But all eigenvalues of A are of the form \\alpha_1' + \\alpha_2', so we are done. \\square\n\n\n\n","context":"Introduction to Representation Theory\t5. Representations of finite groups: Further results\t5.2. Algebraic numbers and algebraic integers\tAlgebraic conjugates of sums are sums of algebraic conjugates","header":"Algebraic conjugates of sums are sums of algebraic conjugates","id":"/5___-Representations-of-finite-groups___-Further-results/5___2___-Algebraic-numbers-and-algebraic-integers/Algebraic-conjugates-of-sums-are-sums-of-algebraic-conjugates/#Chapter5___Lemma5___2___6"}});
